#!/usr/bin/env bash
#
# install-dependency-notices.sh: append the pinned source dependency notices to
# the srtla and MediaMTX copyright files.
#
# Run by the app layer (mkosi.images/app/mkosi.postinst.chroot) after
# install-licence-notices.sh and before doc pruning. It reads only the static,
# checksummed files in dependencies/ (generated by
# tools/generate-dependency-notices.py). No network access, no first-boot work,
# and no installed binary is executed: MediaMTX is identified by hashing it.
#
# dependencies/identity.tsv names the exact installed identities the payloads
# cover: the srtla dpkg package version and architecture, and for MediaMTX the
# binary path, version, release tarball sha256 (recorded in its parent
# copyright file) and the sha256 of the binary in that tarball. Anything else
# (another version, architecture, binary, location or packaging, a missing or
# foreign parent copyright file, or notices already appended) fails the build
# with a message before any file is changed.
#
# Test seams: LICENCE_NOTICES_DESTROOT (install prefix, default /),
# LICENCE_NOTICES_DPKG_QUERY (dpkg-query stand-in), DEPENDENCY_NOTICES_BASE.
#
# shellcheck shell=bash

set -euo pipefail

log() { printf '[dependency-notices] %s\n' "$*" >&2; }
die() { log "FATAL: $*"; exit 1; }

HERE="$(CDPATH='' cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
BASE="${DEPENDENCY_NOTICES_BASE:-${HERE}/dependencies}"
DEST="${LICENCE_NOTICES_DESTROOT:-}"
QUERY="${LICENCE_NOTICES_DPKG_QUERY:-dpkg-query}"
MARKER='SOURCE DEPENDENCY NOTICES ('
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT

# 1. The static payloads, exactly as generated.
[[ -f "${BASE}/SHA256SUMS" ]] || die "missing ${BASE}/SHA256SUMS"
listed="$(awk '{print $2}' "${BASE}/SHA256SUMS" | sort | tr '\n' ' ')"
[[ "${listed}" == 'identity.tsv mediamtx.txt srtla.txt ' ]] \
  || die "SHA256SUMS must list exactly identity.tsv, mediamtx.txt and srtla.txt (lists: ${listed})"
if ! (cd "${BASE}" && sha256sum --check --strict SHA256SUMS) > "${WORK}/sums" 2>&1; then
  die "dependency notice payloads do not match SHA256SUMS: $(grep -v ': OK$' "${WORK}/sums" | tr '\n' ' ')"
fi

# The generated plan binds payload hashes independently of SHA256SUMS. The host
# checker also parses every text record against this plan without source archives.
[[ -f "${BASE}/plan.json" && -f "${BASE}/plan.sha256" ]] || die "missing reviewed notice plan"
read -r expected_plan < "${BASE}/plan.sha256"
[[ "${expected_plan}" =~ ^[0-9a-f]{64}$ ]] || die "invalid plan.sha256"
actual_plan="$(sha256sum "${BASE}/plan.json" | awk '{print $1}')"
[[ "${actual_plan}" == "${expected_plan}" ]] || die "plan.json does not match plan.sha256"
# Deliberately accept only the generator's canonical, flat digest map. A format
# change must update this reader and its host contract rather than skip it.
map_count=0 map_rows=0 in_map=0
digest_row='^    "(identity[.]tsv|mediamtx[.]txt|srtla[.]txt)": "([0-9a-f]{64})"(,?)$'
while IFS= read -r line || [[ -n "${line}" ]]; do
  if [[ "${line}" == '  "payload_sha256": {' ]]; then
    (( map_count += 1 ))
    (( map_count == 1 && ! in_map )) || die "invalid payload digest map: duplicate map"
    in_map=1
  elif (( in_map )); then
    if [[ "${line}" == '  },' || "${line}" == '  }' ]]; then
      (( map_rows == 3 )) || die "invalid payload digest map: expected three entries"
      in_map=0
    elif [[ "${line}" =~ ${digest_row} ]]; then
      (( map_rows += 1 ))
      comma=','
      (( map_rows == 3 )) && comma=''
      [[ "${BASH_REMATCH[3]}" == "${comma}" ]] || die "invalid payload digest map: misplaced comma"
      printf '%s  %s\n' "${BASH_REMATCH[2]}" "${BASH_REMATCH[1]}"
    else
      die "invalid payload digest map: unexpected entry"
    fi
  fi
done < "${BASE}/plan.json" > "${WORK}/planned-sums"
(( map_count == 1 && ! in_map )) || die "invalid payload digest map: missing or unclosed map"
[[ "$(awk '{print $2}' "${WORK}/planned-sums" | sort | tr '\n' ' ')" == \
  'identity.tsv mediamtx.txt srtla.txt ' ]] || die "plan lacks exactly three payload digests"
if ! (cd "${BASE}" && sha256sum --check --strict "${WORK}/planned-sums") > "${WORK}/plan-check" 2>&1; then
  die "notice payloads differ from the reviewed plan"
fi

srtla_rows=() mtx_rows=()
while IFS=$'\t' read -r kind rest || [[ -n "${kind:-}" ]]; do
  [[ -z "${kind}" || "${kind}" == \#* ]] && continue
  case "${kind}" in
    srtla) srtla_rows+=("${rest}") ;;
    mediamtx) mtx_rows+=("${rest}") ;;
    *) die "unknown identity row '${kind}' in identity.tsv" ;;
  esac
done < "${BASE}/identity.tsv"
(( ${#srtla_rows[@]} > 0 && ${#mtx_rows[@]} > 0 )) || die "identity.tsv lacks srtla or mediamtx rows"

# 2. Installed package database, queried once. Failure cannot mean "not installed".
"${QUERY}" -W -f='${Package}\t${db:Status-Status}\t${Version}\t${Architecture}\n' > "${WORK}/installed" \
  || die "dpkg-query failed; cannot establish the installed srtla and MediaMTX identity"

packages=()

# srtla: an installed dpkg package with a covered version and architecture.
IFS=$'\t' read -r srtla_pkg _ <<< "${srtla_rows[0]}"
mapfile -t found < <(awk -F'\t' -v p="${srtla_pkg}" '$1 == p' "${WORK}/installed")
(( ${#found[@]} <= 1 )) || die "${srtla_pkg} has ${#found[@]} dpkg records (multiarch?); not a covered identity"
if (( ${#found[@]} == 1 )); then
  IFS=$'\t' read -r _ status version arch <<< "${found[0]}"
  case "${status}" in
    installed)
      covered=0
      for row in "${srtla_rows[@]}"; do
        IFS=$'\t' read -r _ want_version want_arch <<< "${row}"
        [[ "${version}" == "${want_version}" && "${arch}" == "${want_arch}" ]] && covered=1
      done
      (( covered )) || die "${srtla_pkg} ${version} (${arch}) is installed, but the dependency notices cover only: $(printf '%s ' "${srtla_rows[@]}" | tr '\t' ' '); regenerate them for this pin"
      file="${DEST}/usr/share/doc/${srtla_pkg}/copyright"
      [[ -f "${file}" ]] || die "${srtla_pkg} ${version} is installed but ${file} is missing; install-licence-notices.sh must run first"
      first="$(head -n 1 "${file}")"
      [[ "${first}" == "${srtla_pkg} ${version}" ]] \
        || die "${file} starts with '${first}', not '${srtla_pkg} ${version}'; it is not the parent notice file these notices extend"
      packages+=("${srtla_pkg}")
      ;;
    not-installed | config-files) log "${srtla_pkg} is not installed in this image; skipped" ;;
    *) die "${srtla_pkg} is in dpkg state '${status}'; refusing to guess its identity" ;;
  esac
else
  log "${srtla_pkg} is not installed in this image; skipped"
fi

# MediaMTX: the pinned release binary at its recorded path, identified by hash.
IFS=$'\t' read -r mtx_path mtx_version _ <<< "${mtx_rows[0]}"
if awk -F'\t' '$1 == "mediamtx" && $2 != "not-installed" && $2 != "config-files" {f=1} END {exit !f}' "${WORK}/installed"; then
  die "a mediamtx dpkg package is present; these notices cover only the pinned release binary at ${mtx_path}"
fi
for other in /usr/bin/mediamtx /usr/sbin/mediamtx /usr/local/sbin/mediamtx /opt/mediamtx; do
  [[ "${other}" == "${mtx_path}" ]] && continue
  if [[ -e "${DEST}${other}" || -L "${DEST}${other}" ]]; then
    die "unexpected MediaMTX at ${other}; these notices cover only ${mtx_path}"
  fi
done
binary="${DEST}${mtx_path}"
doc="${DEST}/usr/share/doc/mediamtx/copyright"
has_binary=0 has_doc=0
[[ -e "${binary}" || -L "${binary}" ]] && has_binary=1
[[ -e "${doc}" || -L "${doc}" ]] && has_doc=1
if (( has_binary && has_doc )); then
  [[ -f "${binary}" && ! -L "${binary}" ]] || die "${mtx_path} is not a regular file"
  first="$(head -n 1 "${doc}")"
  [[ "${first}" == "MediaMTX ${mtx_version}, installed as ${mtx_path}" ]] \
    || die "${doc} starts with '${first}'; the dependency notices cover MediaMTX ${mtx_version} at ${mtx_path}"
  mapfile -t tarballs < <(sed -n 's/^Release tarball sha256: //p' "${doc}")
  (( ${#tarballs[@]} == 1 )) || die "${doc} must record exactly one release tarball sha256 (found ${#tarballs[@]})"
  actual="$(sha256sum "${binary}" | awk '{print $1}')"
  matched=''
  for row in "${mtx_rows[@]}"; do
    IFS=$'\t' read -r _ want_version want_arch want_tarball want_binary <<< "${row}"
    [[ "${want_version}" == "${mtx_version}" ]] || die "identity.tsv mixes MediaMTX versions"
    [[ "${tarballs[0]}" == "${want_tarball}" ]] || continue
    [[ "${actual}" == "${want_binary}" ]] \
      || die "${mtx_path} sha256 ${actual} is not the ${want_arch} binary ${want_binary} from release tarball ${want_tarball}"
    matched="${want_arch}"
  done
  [[ -n "${matched}" ]] || die "MediaMTX release tarball ${tarballs[0]} is not covered by the dependency notices"
  packages+=(mediamtx)
elif (( has_binary )); then
  die "${mtx_path} exists but ${doc} is missing; the parent MediaMTX copyright must be installed with it"
elif (( has_doc )); then
  die "${doc} exists but ${mtx_path} is missing; MediaMTX moved or was repackaged, so regenerate the notice identity"
else
  log "MediaMTX is not installed in this image; skipped"
fi

# 3. Preflight every destination before changing any. Preserve the exact parent
# bytes and append the verified payload once only.
for pkg in "${packages[@]}"; do
  dir="${DEST}/usr/share/doc/${pkg}"
  file="${dir}/copyright"
  [[ ! -L "${dir}" && ! -L "${file}" ]] || die "${file} or its directory is a symlink; refusing to write through it"
  [[ -f "${file}" && -s "${file}" ]] || die "${file} is missing or empty"
  if grep -Fq "${MARKER}" "${file}"; then
    die "dependency notices are already present in ${file}; refusing to append twice"
  fi
  cat "${file}" "${BASE}/${pkg}.txt" > "${WORK}/${pkg}"
done
for pkg in "${packages[@]}"; do
  install -m 0644 "${WORK}/${pkg}" "${DEST}/usr/share/doc/${pkg}/copyright"
  log "appended source dependency notices to /usr/share/doc/${pkg}/copyright"
done
